// Package custom provides named numeric types for generated HTTP fixtures.
package custom

type (
	// Float32 is a named float32 used to exercise custom numeric conversion.
	Float32 float32

	// Float64 is a named float64 used to exercise custom numeric conversion.
	Float64 float64

	// Int is a named machine-sized integer used to exercise custom conversion.
	Int int

	// Uint is a named machine-sized unsigned integer used to exercise custom conversion.
	Uint uint
)
